// Churn Chart Tool - n8n Code node (Run Once for All Items)
// Builds a chart from ALL customers so chart numbers always match the data,
// then returns a QuickChart image URL for the agent to show.

const GROUPS = [
  'none', 'gender', 'SeniorCitizen', 'Partner', 'Dependents', 'tenure_group',
  'PhoneService', 'MultipleLines', 'InternetService', 'OnlineSecurity',
  'OnlineBackup', 'DeviceProtection', 'TechSupport', 'StreamingTV',
  'StreamingMovies', 'Contract', 'PaperlessBilling', 'PaymentMethod'
];
const METRICS = {
  churn_rate_pct: 'Churn rate (%)',
  churned: 'Churned customers',
  customers: 'Customers',
  monthly_revenue: 'Monthly revenue ($)',
  churned_monthly_revenue: 'Monthly revenue lost to churn ($)',
  avg_monthly_charge: 'Average monthly charge ($)'
};
const CHART_TYPES = ['bar', 'horizontalBar', 'pie', 'doughnut'];

const input = $('When Executed by Another Workflow').first().json;
const groupBy = String(input.group_by || 'none').trim();
const metric = String(input.metric || 'churn_rate_pct').trim();
const chartType = String(input.chart_type || 'bar').trim();

const errors = [];
if (!GROUPS.includes(groupBy)) errors.push(`group_by must be one of: ${GROUPS.join(', ')}`);
if (!METRICS[metric]) errors.push(`metric must be one of: ${Object.keys(METRICS).join(', ')}`);
if (!CHART_TYPES.includes(chartType)) errors.push(`chart_type must be one of: ${CHART_TYPES.join(', ')}`);
if (errors.length) return [{ json: { error: errors.join(' | ') } }];

const TENURE_ORDER = ['0-12 months', '13-24 months', '25-48 months', '49-72 months'];
function tenureGroup(t) {
  if (t <= 12) return TENURE_ORDER[0];
  if (t <= 24) return TENURE_ORDER[1];
  if (t <= 48) return TENURE_ORDER[2];
  return TENURE_ORDER[3];
}
const round2 = (n) => Math.round(n * 100) / 100;

// 1. Aggregate all customers by the chosen column
const groups = {};
for (const item of $input.all()) {
  const c = item.json;
  let key;
  if (groupBy === 'none') key = 'All customers';
  else if (groupBy === 'tenure_group') key = tenureGroup(Number(c.tenure));
  else key = String(c[groupBy]);
  if (!groups[key]) groups[key] = { group: key, customers: 0, churned: 0, monthly_revenue: 0, churned_monthly_revenue: 0 };
  const g = groups[key];
  const monthly = Number(c.MonthlyCharges) || 0;
  g.customers += 1;
  g.monthly_revenue += monthly;
  if (c.Churn === 'Yes') { g.churned += 1; g.churned_monthly_revenue += monthly; }
}

let rows = Object.values(groups).map((g) => ({
  group: g.group,
  customers: g.customers,
  churned: g.churned,
  churn_rate_pct: round2((g.churned / g.customers) * 100),
  monthly_revenue: round2(g.monthly_revenue),
  churned_monthly_revenue: round2(g.churned_monthly_revenue),
  avg_monthly_charge: round2(g.monthly_revenue / g.customers),
}));

// 2. Order: tenure buckets in time order, everything else highest first
if (groupBy === 'tenure_group') rows.sort((a, b) => TENURE_ORDER.indexOf(a.group) - TENURE_ORDER.indexOf(b.group));
else rows.sort((a, b) => b[metric] - a[metric]);

// 3. Build the Chart.js config (QuickChart uses Chart.js v2 by default)
const isPie = chartType === 'pie' || chartType === 'doughnut';
const title = `${METRICS[metric]} by ${groupBy === 'none' ? 'all customers' : groupBy}`;
const palette = ['#2563eb', '#16a34a', '#f59e0b', '#dc2626', '#7c3aed', '#0891b2'];
const config = {
  type: chartType,
  data: {
    labels: rows.map((r) => r.group),
    datasets: [{
      label: METRICS[metric],
      data: rows.map((r) => r[metric]),
      backgroundColor: isPie ? rows.map((_, i) => palette[i % palette.length]) : '#2563eb',
    }],
  },
  options: {
    title: { display: true, text: title },
    legend: { display: isPie },
    plugins: { datalabels: { display: true, color: isPie ? '#ffffff' : '#111111', anchor: isPie ? 'center' : 'end', align: isPie ? 'center' : 'end' } },
  },
};

const chartUrl = 'https://quickchart.io/chart?w=700&h=400&bkg=white&c=' + encodeURIComponent(JSON.stringify(config));

return [{ json: { title, group_by: groupBy, metric, chart_type: chartType, chart_url: chartUrl, data: rows.map((r) => ({ group: r.group, value: r[metric] })) } }];
